#!/usr/bin/env bash
# grafana/tempo 1.24.4 - base variant: s3-query-observability
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/grafana-tempo-1-24-4.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the s3-query-observability base variant into ./grafana-tempo-1-24-4-s3-query-observability"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/grafana-tempo:1.24.4@sha256:16f07571e893e001c11c5810e8905d7b17e26265ff4dfd972ce77cf1e42cfce1 --base s3-query-observability --work-dir ./grafana-tempo-1-24-4-s3-query-observability --non-interactive --namespace tempo

say "Read what was rendered; nothing has touched the cluster yet"
ls ./grafana-tempo-1-24-4-s3-query-observability/out/manifests

wait_for_crd() {
  crd_name="$1"
  deadline=$(( $(date +%s) + 180 ))
  until kubectl get "crd/${crd_name}" >/dev/null 2>&1; do
    if [ "$(date +%s)" -ge "$deadline" ]; then
      printf "CRD %s did not appear within 180 seconds.\n" "$crd_name" >&2
      return 1
    fi
    sleep 2
  done
  kubectl wait --for=condition=Established --timeout=120s "crd/${crd_name}"
}

say "Ensure the tempo namespace exists"
kubectl create namespace tempo --dry-run=client -o yaml | kubectl apply -f -

say "Check the servicemonitors.monitoring.coreos.com CRD included with this package"
missing_crds=0
if ! kubectl get crd/servicemonitors.monitoring.coreos.com >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  kubectl apply --server-side -f ./grafana-tempo-1-24-4-s3-query-observability/package/prerequisites/target-facts/s3-query-observability-crds.yaml
else
  say "The required CRDs already exist; leave them under their current owner"
fi
wait_for_crd servicemonitors.monitoring.coreos.com

if [ "${REQUIREMENTS_READY:-0}" != "1" ]; then
  cat >&2 <<'EOF_REQUIREMENTS'
This base variant needs resources you must create with your own values first:
  - Secret tempo/tempo-s3-credentials keys access_key,secret_key
    kubectl -n tempo create secret generic tempo-s3-credentials --from-literal=access_key=<value> --from-literal=secret_key=<value>
  - S3-compatible object store tempo/tempo-object-store
    create or bind an S3-compatible endpoint, bucket, and credentials before apply
Complete these prerequisites before applying the rendered objects.
Replace any <...> placeholders with values or files for your environment.
When the resources exist, re-run with:
  REQUIREMENTS_READY=1 bash try.sh
EOF_REQUIREMENTS
  exit 1
fi

if [ -d ./grafana-tempo-1-24-4-s3-query-observability/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./grafana-tempo-1-24-4-s3-query-observability/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./grafana-tempo-1-24-4-s3-query-observability/out/manifests

say "Done. The cluster received exactly the files in ./grafana-tempo-1-24-4-s3-query-observability/out."
